typedef float rational_t;

void* operator new(unsigned int, unsigned int, const char*, int);
#define NEW new(0,__FILE__,__LINE__)

class color32 {
    unsigned int value;
};

class vector2d {
public:
    float x, y;
    vector2d(float _x, float _y) : x(_x), y(_y) {}
};

class stringx {
    unsigned int data[2];
public:
    stringx(const char* str, int len = -1);
    ~stringx();
};

class vr_pmesh {
    char data[172];
public:
    vr_pmesh(unsigned int flags = 0);
    void make_rectangle();
    void shrink_memory_footprint();
};

template<class T> class instance_bank {
public:
    T* find_instance(const stringx&);
    void insert_new_object(T*, const stringx&);
    T* new_instance(T*);
};

class entity {
    char data_to_flags[0x78];
    unsigned int entity_flags;
    char data_to_visrep[0xAC];
protected:
    vr_pmesh* my_visrep;
private:
    char data_after_visrep[0xD4];
public:
    enum { EFLAG_GRAPHICS = 0x100, EFLAG_GRAPHICS_VISIBLE = 0x200 };
    void set_flag(unsigned int flag, bool value) {
        if (value) entity_flags |= flag;
        else entity_flags &= ~flag;
    }
};

class beam : public entity {
    rational_t thickness;
    rational_t max_length;
    color32 my_color;
    char effects[12];
    unsigned int beam_flags;
    char data_to_curr_len[0x54];
    rational_t curr_len;
    char data_to_uv_anim[0x18];
    vector2d uv_anim;
    vector2d uv_coords[2];
    rational_t tiles_per_meter;
    unsigned short effect_id_counter;
    char align_effect_id[2];
    void* my_material;
    bool additive;
public:
    void set_thickness(rational_t);
    void set_max_length(rational_t);
    void set_beam_color(const color32&);
    void construct(rational_t, rational_t, const color32&);
};

extern instance_bank<vr_pmesh> vr_pmesh_bank;

